def _canonical(value):
    """Hashable, ==-faithful canonical form of a JSON-like value.

    The returned object compares equal (via ==) to another value exactly
    when the original values do, which lets us store canonical forms in
    a set for O(1) duplicate lookup.
    """
    try:
        hash(value)
        return value
    except TypeError:
        pass
    if isinstance(value, dict):
        return ("$dict", tuple(sorted((k, _canonical(v)) for k, v in value.items())))
    if isinstance(value, list):
        return ("$list", tuple(_canonical(v) for v in value))
    # Fallback for any other unhashable type.
    return type(value).__name__, str(type(value)), repr(value)


def dedupe(records, key=None):
    seen = set()
    out = []
    for r in records:
        k = key(r) if key else r
        ck = _canonical(k)
        if ck not in seen:
            seen.add(ck)
            out.append(r)
    return out
